import{readFile,writeFile,mkdir}from'node:fs/promises';import{resolve}from'node:path';
const registry=JSON.parse(await readFile('/tmp/hb-current-published-registry.json','utf8'));const report={scope:'ONLY_CURRENT_PARTIAL_SERVICE_FIELDS; previously accepted services excluded',sourceSha:process.env.HB_SOURCE_SHA,capturedAt:new Date().toISOString(),publishedServices:registry.services.length,partials:registry.services.filter(s=>!s.verification?.detailsVerified).map(s=>({id:s.id,slug:s.slug,name:s.name,sourceRegistry:s.sourceRegistry,destinationKind:s.destinationKind,emirate:s.emirate,authority:s.authority,verification:s.verification,sourceUrl:s.officialInformationUrl,applicationUrl:s.officialCtaUrl,documents:s.documents,fees:s.governmentFees,duration:s.processingTime,conditions:s.conditions,eligibilityScope:s.eligibilityScope,localizedDetails:s.localizedDetails,scopedGuidance:s.scopedGuidance}))};const out=resolve('diagnostics/partial-fact-continuation-20261105');await mkdir(out,{recursive:true});await writeFile(out+'/report.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({publishedServices:report.publishedServices,partialServices:report.partials.length,scope:report.scope}));
